package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number n = NumberUtils.createNumber("123");
        assertTrue(n instanceof Integer);
        assertEquals(123, n.intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        Number n = NumberUtils.createNumber("1234567890123");
        assertTrue(n instanceof Long);
        assertEquals(1234567890123L, n.longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        Number n = NumberUtils.createNumber("123456789012345678901234567890");
        assertTrue(n instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_Float() {
        Number n = NumberUtils.createNumber("123.456");
        assertTrue(n instanceof Float);
        assertEquals(123.456f, n.floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_Double() {
        Number n = NumberUtils.createNumber("123.456789012345");
        assertTrue(n instanceof Double);
        assertEquals(123.456789012345, n.doubleValue(), 0.0000000000001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        // More than 16 decimal places triggers BigDecimal
        Number n = NumberUtils.createNumber("123.1234567890123456789");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_Hex_Int() {
        Number n = NumberUtils.createNumber("0x7FFFFFFF");
        assertTrue(n instanceof Integer);
    }

    @Test
    public void testCreateNumber_Hex_Long() {
        Number n = NumberUtils.createNumber("0x7FFFFFFFFFFFFFFF");
        assertTrue(n instanceof Long);
    }

    @Test
    public void testCreateNumber_Hex_BigInt() {
        Number n = NumberUtils.createNumber("0x7FFFFFFFFFFFFFFFFFFFFFFFFFFF");
        assertTrue(n instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_Hex_Prefixes() {
        assertTrue(NumberUtils.createNumber("0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("#123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-#123") instanceof Integer);
    }

    @Test
    public void testCreateNumber_Hex_LeadingZeros() {
        // Testing the loop that strips leading zeros in hex
        Number n = NumberUtils.createNumber("0x0000000000000001");
        assertTrue(n instanceof Integer);
        assertEquals(1, n.intValue());
    }

    @Test
    public void testCreateNumber_Suffix_L() {
        Number n = NumberUtils.createNumber("123L");
        assertTrue(n instanceof Long);
        assertEquals(123L, n.longValue());

        Number nBig = NumberUtils.createNumber("12345678901234567890L");
        assertTrue(nBig instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_Suffix_F() {
        Number n = NumberUtils.createNumber("123.456F");
        assertTrue(n instanceof Float);
    }

    @Test
    public void testCreateNumber_Suffix_D() {
        Number n = NumberUtils.createNumber("123.456D");
        assertTrue(n instanceof Double);
    }

    @Test
    public void testCreateNumber_Exponent() {
        Number n = NumberUtils.createNumber("1.23e4");
        assertTrue(n instanceof Float || n instanceof Double);
    }

    @Test
    public void testCreateNumber_Invalid_Suffix() {
        // Test the default case in the switch
        try {
            NumberUtils.createNumber("123X");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("is not a valid number"));
        }
    }

    @Test
    public void testCreateNumber_Invalid_Exponent_Format() {
        try {
            NumberUtils.createNumber("1.2e");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Caught by the logic in the method
        }
    }

    @Test
    public void testCreateNumber_AllZeros_Logic() {
        // Tests the allZeros logic used in precision checks
        Number n = NumberUtils.createNumber("0.00000000000000000000");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_Float_Overflow_Fallback() {
        // A float that is too big for Float should fallback to Double/BigDecimal
        Number n = NumberUtils.createNumber("1e40F");
        assertTrue(n instanceof Double || n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_Decimal_Precision_Boundaries() {
        // numDecimals <= 7 -> Float
        Number n1 = NumberUtils.createNumber("1.1234567");
        assertTrue(n1 instanceof Float);

        // numDecimals <= 16 -> Double
        Number n2 = NumberUtils.createNumber("1.123456789012345");
        assertTrue(n2 instanceof Double);

        // numDecimals > 16 -> BigDecimal
        Number n3 = NumberUtils.createNumber("1.12345678901234567");
        assertTrue(n3 instanceof BigDecimal);
    }
}
